async function load(slug:'believeland'|'robocop'){const seeded=seedSetup(slug);const persisted=await store.getSetup(seeded.season.id);setup=slug==='believeland'&&persisted?{...persisted,settings:seeded.settings,rosterSlots:seeded.rosterSlots,positionLimits:seeded.positionLimits,draft:{...persisted.draft,draftType:seeded.draft.draftType,draftDate:null,pickTimerSeconds:null,keeperCount:0,liveStartRound:1}}:persisted??seeded;await store.saveSetup(setup);[philosophy,interests,intents,messages]=await Promise.all([store.getPhilosophy(setup.league.id,setup.season.id),store.getInterests(setup.league.id,setup.season.id),store.getIntents(setup.league.id,setup.season.id),store.getMessages(setup.league.id,setup.season.id)]);const format=scoringFormatFor(setup),fixtures=playerPool();[playerData,espnRankings]=await Promise.all([store.getPlayerData(setup.league.id,setup.season.year,format),store.getEspnRankingSource(setup.league.id)]);if(espnRankings?.scoringFormat!==format)espnRankings=undefined;const players=selectPlayerPool(fixtures,playerData);const sessionId=localStorage.getItem(`draft-session-${slug}`);ctx=sessionId?await store.loadDraft(sessionId,setup,players,fixtures):undefined;if(!sharedLoads.has(setup.league.id)){sharedLoads.add(setup.league.id);queueMicrotask(()=>void syncSharedPlayerData(slug))}}
async function syncSharedPlayerData(slug:'believeland'|'robocop'){try{const snapshot=await draftCloud.loadLatestSharedPlayerSnapshot(setup.season.year,scoringFormatFor(setup));if(!snapshot||playerData&&Date.parse(playerData.createdAt)>=Date.parse(snapshot.createdAt))return;await store.savePlayerData(setup.league.id,snapshot);playerData=snapshot;if(ctx){const reconciled=reconcileDraftHistory(ctx.events,selectPlayerPool(playerPool(),snapshot),playerPool());if(reconciled.unresolved.length)throw new DraftHistoryRepairError(reconciled.unresolved);ctx={...ctx,players:reconciled.players,events:reconciled.events};await store.saveDraft(ctx)}if(location.hash.startsWith(`#/${slug}`))void safeRoute()}catch(error){if(error instanceof DraftHistoryRepairError)renderHistoryRepair(error)/* Otherwise the last good compatible local snapshot remains authoritative offline. */}}
function shell(body:string){const reminder=reminderMarkup(new Date(),localStorage.getItem(HOF_REMINDER_STORAGE_KEY)==='true');root.innerHTML=`<div class="dev-banner">${document.querySelector('.dev-banner')?.textContent??''}</div><header><a href="#/">FD</a><b>Fantasy Draft Assistant</b><span id="cloud">Connecting…</span>${draftCloud.client?'<button id="sign-out-header">Sign Out</button>':''}</header>${reminder}${body}<footer>Private internal application · Not linked from OliPoly customer pages</footer>`;void draftCloud.status().then(x=>{const el=document.querySelector('#cloud');if(el)el.textContent=x.replaceAll('-',' ').toUpperCase()});document.querySelector('#sign-out-header')?.addEventListener('click',()=>void draftCloud.signOut().then(()=>location.reload()));document.querySelector('#hof-reminder-done')?.addEventListener('click',()=>{localStorage.setItem(HOF_REMINDER_STORAGE_KEY,'true');document.querySelector('.hof-reminder')?.remove()})}
function leagueCards(){shell(`<main><p class="eyebrow">PRIVATE · 2026</p><h1>League Select</h1><div class="cards">${['believeland','robocop'].map(s=>{const x=seedSetup(s as 'believeland'|'robocop');return`<a href="#/${s}"><small>${x.settings.scoringLabel}</small><h2>${x.league.name}</h2><p>12 teams · ${x.draft.keeperCount?`${x.draft.keeperCount} keepers`:'Redraft'}</p></a>`}).join('')}</div></main>`)}
async function dashboard(slug:'believeland'|'robocop'){await load(slug);shell(`<main><a href="#/">← Leagues</a><p class="eyebrow">${setup.season.name}</p><h1>${setup.league.name}</h1><p>${setup.settings.scoringLabel} · ${setup.rosterSlots.filter(x=>x.kind!=='ir').reduce((n,x)=>n+x.count,0)} roster · ${setup.rosterSlots.find(x=>x.kind==='ir')?.count??0} IR</p><div class="stats"><span><b>${setup.teams.length}/12</b> Managers</span><span><b>${setup.draft.orderStatus}</b> Order</span><span><b>${setup.keepers.length}/${setup.draft.keeperCount*12||0}</b> Keepers</span><span><b>${ctx?rebuildDraftState(ctx).status:'NOT_STARTED'}</b> Draft</span></div><div class="actions"><a href="#/${slug}/settings">League Settings</a><a href="#/${slug}/managers">Teams & Managers</a><a href="#/${slug}/order">Draft Order</a>${slug==='robocop'?`<a href="#/${slug}/keepers">Keepers</a>`:''}<a href="#/${slug}/ownership">Pick Ownership</a><a href="#/${slug}/draft">Draft Test / Session</a><a href="#/${slug}/board">Draft Board</a><a href="#/${slug}/rankings">Rankings</a><a href="#/${slug}/draft">Review Draft Philosophy · ${philosophy.preferences.length}</a></div><div class="context-summary"><b>PLAYER INTERESTS</b> · INTERESTED ${interests.filter(x=>x.state==='INTERESTED').length} · WATCHING ${interests.filter(x=>x.state==='WATCH').length} · FADES ${interests.filter(x=>x.state==='FADE').length}<br><b>ACTIVE INTENTS</b> · ${intents.filter(x=>x.status==='ACTIVE').length}</div><p>Personal context is local to this league and season; cloud sync is deferred.</p><div class="data-status">${playerDataStatusMarkup(playerData,aiStatus)}</div></main>`)}
