function keepers(){shell(`<main><a href="#/robocop">← Dashboard</a><p class="eyebrow">${setup.keeperLock.status}</p><h1>RoboCop Keepers</h1><div class="keeper-head"><b>August 23, 2026 @ 4:00 PM EDT</b><button id="lock">${setup.keeperLock.status==='locked'?'UNLOCK':'LOCK'} KEEPERS</button></div><p>${setup.keepers.length} / 36 provisional assignments</p><div class="keepers">${setup.teams.map(t=>`<section><h3>${name(t.id)}</h3>${[1,2,3].map(i=>`<input data-team="${t.id}" data-slot="${i}" value="${setup.keepers.find(k=>k.teamId===t.id&&k.keeperSlot===i)?.player.displayName??''}" placeholder="Keeper ${i}" ${setup.keeperLock.status==='locked'?'disabled':''}>`).join('')}</section>`).join('')}</div></main>`);document.querySelector('#lock')?.addEventListener('click',async()=>{setup=lockKeepers(setup,setup.keeperLock.status!=='locked');await store.saveSetup(setup);keepers()});document.querySelectorAll<HTMLInputElement>('[data-slot]').forEach(el=>el.onchange=async()=>{try{setup=setKeeper(setup,el.dataset.team!,Number(el.dataset.slot),el.value);await store.saveSetup(setup)}catch(e){alert((e as Error).message);keepers()}})}
